INSERT INTO control_edge_usage_events(tenant_id,executor_id,session_id,seq,kind,run_id,occurred_at_ms,started_seq,source_session_id,provider,model,protocol,event_json)
SELECT e.tenant_id,e.executor_id,e.session_id,e.seq,json_extract(e.event_json,'$.type'),json_extract(e.event_json,'$.run_id'),CAST(json_extract(e.event_json,'$.occurred_at_ms') AS BIGINT),CAST(json_extract(e.event_json,'$.started_seq') AS BIGINT),json_extract(e.event_json,'$.source_session_id'),json_extract(e.event_json,'$.route.provider'),json_extract(e.event_json,'$.route.model'),json_extract(e.event_json,'$.route.protocol'),e.event_json
FROM control_edge_events e WHERE json_extract(e.event_json,'$.type') IN ('provider_usage_started','provider_usage_finished')
